135	        HttpStatus status = HttpStatus.BAD_REQUEST;
136	        BindingResult bindingResult = e.getBindingResult();
137	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
138	        if (bindingResult.hasErrors()) {
139	            List<FieldError> fieldErrors = bindingResult.getFieldErrors();
140	            logger.debug("Validation error at {} {}: {}",
141	                request.getMethod(),
142	                request.getRequestURI(),
143	                fieldErrors);
144	            detail.setProperty("schemaValidationErrors", toSchemaValidationErrors(fieldErrors));
145	            detail.setProperty("errors", toRejectedFieldNames(fieldErrors));
146	        }
147	        return ResponseEntity.status(status).body(detail);
